"""
Data-preserving prefix-cache-oriented dataframe reordering.

The evaluator scores concatenated row strings with an exact character Trie.
This implementation builds a small bounded set of valid column-order
constructions, measures their exact sorted-row LCP reuse, and returns the best.

Construction candidates:
1. Original column order.
2. Global order ranked by length-weighted repeated-value mass.
3. Bounded conditional prefix partitioning using factorized cell values.

All returned values are original source values.  Temporary strings are used only
for evaluator-compatible scoring and never alter stored dataframe cells.
"""

from typing import List, Tuple
import heapq

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Construct bounded data-preserving column permutation candidates."""

    def __init__(self, df: pd.DataFrame = None):
        """Store an optional dataframe reference without mutating it."""
        self.df = df

    @staticmethod
    def _string_matrix(df: pd.DataFrame) -> np.ndarray:
        """Build evaluator-compatible cell strings while preserving source values."""
        rows, cols = df.shape
        result = np.empty((rows, cols), dtype=object)

        for col_id in range(cols):
            column = df.iloc[:, col_id]
            try:
                # This intentionally mirrors fillna("").astype(str) used by scoring.
                result[:, col_id] = column.fillna("").astype(str).to_numpy(
                    dtype=object, copy=False
                )
            except (TypeError, ValueError):
                values = column.to_numpy(dtype=object, copy=False)
                converted = []
                for value in values:
                    try:
                        missing = pd.isna(value)
                        missing = isinstance(missing, (bool, np.bool_)) and bool(missing)
                    except Exception:
                        missing = False
                    converted.append("" if missing else str(value))
                result[:, col_id] = converted

        return result

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute one character LCP via binary search and C-level slice equality."""
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_reuse(cls, serialized_rows: List[str]) -> int:
        """Compute exact ideal serial-Trie reuse from lexicographically adjacent LCPs."""
        if len(serialized_rows) < 2:
            return 0

        ordered = sorted(serialized_rows)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _serialize(strings: np.ndarray, orders: List[List[int]]) -> List[str]:
        """Serialize each row according to its source-column permutation."""
        return [
            "".join(strings[row_id, order])
            for row_id, order in enumerate(orders)
        ]

    @staticmethod
    def _dependency_edges(columns, one_way_dep) -> List[Tuple[int, int]]:
        """Resolve unambiguous substring dependency names into positional edges."""
        edges = []

        for pair in one_way_dep or []:
            if not isinstance(pair, (tuple, list)) or len(pair) != 2:
                continue

            left = [
                index for index, column in enumerate(columns)
                if str(pair[0]) in str(column)
            ]
            right = [
                index for index, column in enumerate(columns)
                if str(pair[1]) in str(column)
            ]

            if len(left) == 1 and len(right) == 1 and left[0] != right[0]:
                edges.append((left[0], right[0]))

        return edges

    @staticmethod
    def _apply_dependencies(
        order: List[int],
        edges: List[Tuple[int, int]],
    ) -> List[int]:
        """Stable-topologically sort a proposed order, retaining it on cycles."""
        if not edges:
            return list(order)

        rank = {column: position for position, column in enumerate(order)}
        children = {column: [] for column in order}
        indegree = {column: 0 for column in order}

        for left, right in edges:
            if left in indegree and right in indegree:
                children[left].append(right)
                indegree[right] += 1

        ready = [(rank[column], column) for column in order if indegree[column] == 0]
        heapq.heapify(ready)
        result = []

        while ready:
            _, current = heapq.heappop(ready)
            result.append(current)

            for child in children[current]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    heapq.heappush(ready, (rank[child], child))

        return result if len(result) == len(order) else list(order)

    @staticmethod
    def _merge_units(columns, col_merge) -> List[List[int]]:
        """Create non-overlapping adjacency units for requested merged columns."""
        used = set()
        units = []

        for group in col_merge or []:
            if not isinstance(group, (tuple, list)):
                continue

            positions = []
            for name in group:
                matches = [
                    index for index, column in enumerate(columns)
                    if column == name and index not in used
                ]
                if len(matches) == 1:
                    positions.append(matches[0])

            if len(positions) > 1:
                units.append(positions)
                used.update(positions)

        for index in range(len(columns)):
            if index not in used:
                units.append([index])

        return units

    @staticmethod
    def _factorize(
        strings: np.ndarray,
        retain_codes: bool,
    ):
        """
        Factorize each column once and calculate repeated-character mass.

        The score is sum(len(value) * count(value) * (count(value)-1)).
        Codes are retained only when conditional partitioning is affordable.
        """
        rows, cols = strings.shape
        codes = np.empty((rows, cols), dtype=np.int32) if retain_codes else None
        lengths = []
        scores = np.zeros(cols, dtype=np.int64)

        for col in range(cols):
            code, unique_values = pd.factorize(strings[:, col], sort=False)
            code = code.astype(np.int32, copy=False)
            value_lengths = np.fromiter(
                (len(value) for value in unique_values),
                dtype=np.int64,
                count=len(unique_values),
            )
            counts = np.bincount(code, minlength=len(unique_values)).astype(
                np.int64, copy=False
            )

            scores[col] = int(np.sum(value_lengths * counts * (counts - 1)))
            lengths.append(value_lengths)

            if retain_codes:
                codes[:, col] = code

        return codes, lengths, scores

    def _global_order(
        self,
        scores: np.ndarray,
        units: List[List[int]],
        dependencies: List[Tuple[int, int]],
    ) -> List[int]:
        """Rank merge-safe units by repeated character mass and honor dependencies."""
        ranked_units = sorted(
            units,
            key=lambda unit: (-sum(int(scores[col]) for col in unit), min(unit)),
        )

        order = []
        for unit in ranked_units:
            order.extend(sorted(unit, key=lambda col: (-int(scores[col]), col)))

        return self._apply_dependencies(order, dependencies)

    @staticmethod
    def _local_score(
        row_ids: np.ndarray,
        column: int,
        codes: np.ndarray,
        lengths: List[np.ndarray],
    ) -> int:
        """Calculate repeated full-value character mass inside one row partition."""
        selected = codes[row_ids, column]
        if len(selected) < 2:
            return 0

        counts = np.bincount(selected).astype(np.int64, copy=False)
        return int(np.sum(lengths[column][:len(counts)] * counts * (counts - 1)))

    def _conditional_orders(
        self,
        codes: np.ndarray,
        lengths: List[np.ndarray],
        global_order: List[int],
        dependencies: List[Tuple[int, int]],
        row_stop,
        col_stop,
    ) -> List[List[int]]:
        """
        Build row-specific orders using bounded conditional repeated-value groups.

        Each active group selects the remaining field with greatest local
        length-weighted repetition, places it at the prefix, and recurses only
        into duplicate-value children.  The suffix always uses global order.
        """
        rows, cols = codes.shape
        orders = [list(global_order) for _ in range(rows)]

        if rows < 2 or cols < 2:
            return orders

        depth_limit = min(cols, 10)
        for limit in (row_stop, col_stop):
            if limit is not None:
                try:
                    depth_limit = min(depth_limit, max(1, int(limit)))
                except Exception:
                    pass

        candidate_cap = min(cols, 28)
        max_nodes = 160
        rank = {column: position for position, column in enumerate(global_order)}

        stack = [(np.arange(rows, dtype=np.int64), [], 0)]
        nodes = 0

        while stack and nodes < max_nodes:
            row_ids, prefix, depth = stack.pop()
            nodes += 1

            if len(row_ids) < 2 or depth >= depth_limit:
                continue

            used = set(prefix)
            remaining = [column for column in global_order if column not in used]
            if not remaining:
                continue

            best_column = None
            best_score = 0

            for column in remaining[:candidate_cap]:
                score = self._local_score(row_ids, column, codes, lengths)
                if (
                    score > best_score
                    or (
                        score == best_score
                        and best_column is not None
                        and rank[column] < rank[best_column]
                    )
                ):
                    best_column = column
                    best_score = score

            if best_column is None or best_score <= 0:
                continue

            next_prefix = prefix + [best_column]
            prefix_set = set(next_prefix)
            local_order = next_prefix + [
                column for column in global_order if column not in prefix_set
            ]
            local_order = self._apply_dependencies(local_order, dependencies)

            for row_id in row_ids:
                orders[int(row_id)] = local_order

            selected = codes[row_ids, best_column]
            sorting = np.argsort(selected, kind="stable")
            grouped_rows = row_ids[sorting]
            grouped_codes = selected[sorting]

            start = 0
            while start < len(grouped_rows):
                end = start + 1
                while (
                    end < len(grouped_rows)
                    and grouped_codes[end] == grouped_codes[start]
                ):
                    end += 1

                if end - start > 1:
                    stack.append((grouped_rows[start:end], next_prefix, depth + 1))

                start = end

        return orders

    @staticmethod
    def _materialize(df: pd.DataFrame, orders: List[List[int]]) -> pd.DataFrame:
        """Apply row-specific source permutations into an object-typed dataframe."""
        source = df.to_numpy(dtype=object, copy=True)
        rows, cols = source.shape
        output = np.empty((rows, cols), dtype=object)

        for row_id, order in enumerate(orders):
            output[row_id, :] = source[row_id, order]

        return pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
        )

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """
        Select the best bounded construction using exact serialized Trie reuse.

        Identity, global frequency ranking, and conditional partitioning are
        compared only once each.  No source row, value, column, or index entry
        is changed; only within-row output positions are permuted.
        """
        rows, cols = df.shape
        columns = list(df.columns)

        if rows == 0 or cols == 0:
            return df.copy(), [[] for _ in range(rows)]

        strings = self._string_matrix(df)
        units = self._merge_units(columns, col_merge)
        dependencies = self._dependency_edges(columns, one_way_dep)
        has_merge = any(len(unit) > 1 for unit in units)

        # A full integer code matrix is useful for conditional grouping but is
        # intentionally bounded on very wide frames.
        retain_codes = (rows * cols) <= 20_000_000 and not has_merge
        codes, lengths, frequency_scores = self._factorize(strings, retain_codes)

        identity_order = list(range(cols))
        global_order = self._global_order(
            frequency_scores,
            units,
            dependencies,
        )

        candidates = [
            [list(identity_order) for _ in range(rows)],
            [list(global_order) for _ in range(rows)],
        ]

        if retain_codes and codes is not None:
            candidates.append(
                self._conditional_orders(
                    codes,
                    lengths,
                    global_order,
                    dependencies,
                    row_stop,
                    col_stop,
                )
            )

        best_orders = candidates[0]
        best_score = -1

        for candidate in candidates:
            score = self._trie_reuse(self._serialize(strings, candidate))
            if score > best_score:
                best_score = score
                best_orders = candidate

        reordered = self._materialize(df, best_orders)
        column_orderings = [
            [columns[position] for position in order]
            for order in best_orders
        ]

        return reordered, column_orderings

